result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/quiz_app.py", "content": """"Tiny quiz-taking HTTP API built with Flask."""

import json

from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory storage: quiz_id -> quiz dict
QUIZZES = {}


class ApiError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.message = message
        self.status = status


@app.errorhandler(ApiError)
def handle_api_error(err):
    return jsonify({"error": err.message}), err.status


@app.errorhandler(404)
def handle_404(_err):
    return jsonify({"error": "not found"}), 404


@app.errorhandler(405)
def handle_405(_err):
    return jsonify({"error": "method not allowed"}), 405


def _validate_quiz_payload(data):
    """Return (title, questions) or raise ApiError(400)."""
    if not isinstance(data, dict):
        raise ApiError("body must be a JSON object")
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        raise ApiError("'title' must be a non-empty string")
    questions = data.get("questions")
    if not isinstance(questions, list) or not questions:
        raise ApiError("'questions' must be a non-empty list")
    cleaned = []
    for i, q in enumerate(questions):
        if not isinstance(q, dict):
            raise ApiError(f"questions[{i}] must be an object")
        text = q.get("text")
        choices = q.get("choices")
        answer = q.get("answer")
        if not isinstance(text, str) or not text.strip():
            raise ApiError(f"questions[{i}].text must be a non-empty string")
        if (
            not isinstance(choices, list)
            or len(choices) != 4
            or not all(isinstance(c, str) and c.strip() for c in choices)
        ):
            raise ApiError(
                f"questions[{i}].choices must be a list of 4 non-empty strings"
            )
        if not isinstance(answer, int) or isinstance(answer, bool) or not 0 <= answer <= 3:
            raise ApiError(f"questions[{i}].answer must be an integer in 0..3")
        cleaned.append({"text": text, "choices": list(choices), "answer": answer})
    return title, cleaned


def _permutation(seed, quiz_id, qi, n=4):
    """Deterministic display order of original choice indices."""
    import random

    rng = random.Random(f"{quiz_id}:{qi}:{seed}")
    perm = list(range(n))
    rng.shuffle(perm)
    return perm


def _encode_token(perm):
    """Opaque token encoding the displayed->original mapping."""
    return json.dumps(perm)


def _decode_token(token):
    try:
        perm = json.loads(token)
    except (TypeError, ValueError):
        raise ApiError("invalid token")
    if (
        not isinstance(perm, list)
        or sorted(perm) != [0, 1, 2, 3]
        or not all(isinstance(p, int) for p in perm)
    ):
        raise ApiError("invalid token")
    return perm


@app.post("/quizzes")
def create_quiz():
    data = request.get_json(silent=True)
    if data is None:
        raise ApiError("request body must be valid JSON")
    title, questions = _validate_quiz_payload(data)
    quiz_id = str(len(QUIZZES) + 1)
    QUIZZES[quiz_id] = {"id": quiz_id, "title": title, "questions": questions}
    return jsonify({"id": quiz_id}), 201


@app.get("/quizzes/<quiz_id>/take")
def take_quiz(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        raise ApiError("quiz not found", status=404)
    raw_seed = request.args.get("seed")
    if raw_seed is None:
        raise ApiError("'seed' query parameter is required")
    try:
        seed = int(raw_seed)
    except ValueError:
        raise ApiError("'seed' must be an integer")

    out_questions = []
    for qi, q in enumerate(quiz["questions"]):
        perm = _permutation(seed, quiz_id, qi)
        out_questions.append(
            {
                "text": q["text"],
                "choices": [q["choices"][orig] for orig in perm],
                "token": _encode_token(perm),
            }
        )
    return jsonify(
        {"id": quiz["id"], "title": quiz["title"], "seed": seed, "questions": out_questions}
    )


@app.post("/quizzes/<quiz_id>/attempts")
def submit_attempt(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        raise ApiError("quiz not found", status=404)
    data = request.get_json(silent=True)
    if data is None:
        raise ApiError("request body must be valid JSON")
    if not isinstance(data, dict):
        raise ApiError("body must be a JSON object")
    seed = data.get("seed")
    if not isinstance(seed, int) or isinstance(seed, bool):
        raise ApiError("'seed' must be an integer")
    responses = data.get("responses")
    if not isinstance(responses, list) or len(responses) != len(quiz["questions"]):
        raise ApiError(
            f"'responses' must be a list of {len(quiz['questions'])} integers"
        )
    for i, r in enumerate(responses):
        if not isinstance(r, int) or isinstance(r, bool) or not 0 <= r <= 3:
            raise ApiError(f"responses[{i}] must be an integer in 0..3")

    correct = []
    for qi, (q, shown) in enumerate(zip(quiz["questions"], responses)):
        perm = _permutation(seed, quiz_id, qi)
        original_index = perm[shown]  # displayed position -> original choice index
        correct.append(original_index == q["answer"])

    score = sum(correct) / len(correct) if correct else 0.0
    return jsonify({"score": float(score), "correct": correct})
